import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, it, expect } from "vitest";
import type {
  InventoryCreate,
  InventoryOut,
  InventoryPatch,
  InventoryWithProductOut,
  Location,
  ProductCreate,
  ProductOut,
  ShoppingListItemOut,
} from "@/types";

/** The API description generated by the backend and checked into the repository. Tests run from `frontend/`. */
const OPENAPI_PATH = resolve(process.cwd(), "../docs/openapi.json");

interface SchemaObject {
  properties: Record<string, { anyOf?: Array<{ enum?: string[] }> }>;
  required?: string[];
}

const schemas = JSON.parse(readFileSync(OPENAPI_PATH, "utf8")).components.schemas as Record<string, SchemaObject>;

/** Every key of the nutrition block, which `ProductOut` and `ProductCreate` share. */
const NUTRITION_KEYS = {
  kcal_per_100g: true,
  fat_per_100g: true,
  saturated_fat_per_100g: true,
  carbs_per_100g: true,
  sugars_per_100g: true,
  fiber_per_100g: true,
  proteins_per_100g: true,
  salt_per_100g: true,
} as const;

/*
 * Each map lists every key of a frontend type. `Record<keyof T, true>` makes TypeScript fail to
 * compile when a key is missing or unknown, so the maps cannot drift from `types.ts`. The tests
 * then compare them with the backend's API description.
 */
const PRODUCT_OUT: Record<keyof ProductOut, true> = {
  ...NUTRITION_KEYS,
  ean: true,
  name: true,
  brand: true,
  description: true,
  image_url: true,
  category: true,
  quantity_desc: true,
  source: true,
};
const PRODUCT_CREATE: Record<keyof ProductCreate, true> = {
  ...NUTRITION_KEYS,
  ean: true,
  name: true,
  brand: true,
  description: true,
  image_url: true,
  category: true,
  quantity_desc: true,
};
const INVENTORY_OUT: Record<keyof InventoryOut, true> = {
  id: true,
  ean: true,
  quantity: true,
  threshold: true,
  unit: true,
  location: true,
  drawer: true,
  frozen_at: true,
  notes: true,
};
const INVENTORY_CREATE: Record<keyof InventoryCreate, true> = {
  ean: true,
  quantity: true,
  threshold: true,
  unit: true,
  location: true,
  drawer: true,
  frozen_at: true,
  notes: true,
};
const INVENTORY_PATCH: Record<keyof InventoryPatch, true> = {
  quantity: true,
  threshold: true,
  unit: true,
  location: true,
  drawer: true,
  frozen_at: true,
  notes: true,
};
const INVENTORY_WITH_PRODUCT: Record<keyof InventoryWithProductOut, true> = { inventory: true, product: true, low: true };
const SHOPPING_ITEM: Record<keyof ShoppingListItemOut, true> = {
  ean: true,
  name: true,
  quantity: true,
  threshold: true,
  unit: true,
  image_url: true,
};
const LOCATIONS: Record<Location, true> = { pantry: true, freezer: true };

/**
 * Reads the property names of a schema in the API description.
 *
 * @param name - The schema name, such as `InventoryOut`.
 * @returns The sorted property names.
 */
function backendKeys(name: string): string[] {
  return Object.keys(schemas[name].properties).sort();
}

describe("Frontend types match the backend API description", () => {
  it.each([
    ["ProductOut", PRODUCT_OUT],
    ["ProductCreate", PRODUCT_CREATE],
    ["InventoryOut", INVENTORY_OUT],
    ["InventoryCreate", INVENTORY_CREATE],
    ["InventoryPatch", INVENTORY_PATCH],
    ["InventoryWithProductOut", INVENTORY_WITH_PRODUCT],
    ["ShoppingListItemOut", SHOPPING_ITEM],
  ])("test_types_%s_hasTheSameKeysAsTheBackendSchema", (schema, frontendKeys) => {
    expect(Object.keys(frontendKeys).sort()).toEqual(backendKeys(schema));
  });

  it("test_types_location_hasTheSameValuesAsTheBackendLiteral", () => {
    const options = schemas.InventoryCreate.properties.location.anyOf ?? [];
    const backend = options.flatMap((option) => option.enum ?? []).sort();
    expect(Object.keys(LOCATIONS).sort()).toEqual(backend);
  });

  it.each([
    ["InventoryCreate", ["ean", "quantity", "threshold"]],
    ["ProductCreate", ["ean", "name"]],
    ["InventoryOut", ["ean", "id", "quantity", "threshold", "unit"]],
  ])("test_types_%s_requiresTheFieldsTheFrontendAlwaysSends", (schema, required) => {
    expect([...(schemas[schema].required ?? [])].sort()).toEqual(required);
  });
});
